WITH exploded AS (SELECT id, customer_id, created_at, coupon_codes, attr_key, value FROM carts LATERAL VIEW EXPLODE(attributes) t AS attr_key, value) SELECT *, FIRST_VALUE(attr_key, TRUE) OVER (PARTITION BY customer_id ORDER BY created_at, id, attr_key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_attr_key, FIRST_VALUE(attr_key, TRUE) OVER w_running AS first_known_attr_key_2 FROM exploded WINDOW w_running AS (PARTITION BY attr_key ORDER BY created_at, id, attr_key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
